sp_widget.client_script:
api.controller=function() {
  /* widget controller */
  var c = this;
};

sp_widget.css:
.qr-container {
    text-align: center;
    background: white;
    max-width: 600px;
    margin: 40px auto;
    padding: 40px;
    border-radius: 12px;
    box-shadow: 0 3px 15px rgba(0,0,0,0.15);
}

.qr-container h1 {
    color: #17365d;
    margin-bottom: 10px;
}

.qr-container h2 {
    color: #333;
    margin-bottom: 15px;
}

.instruction {
    font-size: 16px;
    color: #555;
}

.qr-box {
    margin: 25px auto;
    padding: 20px;
    width: 390px;
    max-width: 90%;
    border: 2px solid #ddd;
    border-radius: 10px;
    background: white;
}

.qr-image {
    width: 350px;
    height: 350px;
    max-width: 100%;
}

.scan-text {
    font-size: 18px;
    font-weight: bold;
    color: #087f5b;
}

.interview-info {
    color: #666;
    margin-top: 15px;
}

.error-box {
    text-align: center;
    background: #ffe5e5;
    color: #b00020;
    padding: 30px;
    margin: 40px auto;
    max-width: 600px;
}

sp_widget.script:
(function() {

    data.success = false;
    data.message = '';
    data.interviewNumber = '';

    // Get value from URL
    var identifier = $sp.getParameter('interview_id');

    if (!identifier) {
        data.message = 'Interview ID is missing from the URL.';
        return;
    }

    // Mock Interview table
    var gr = new GlideRecord('x_snc_campus360_mock_interview');

    if (!gr.isValid()) {
        data.message = 'Mock Interview table is invalid.';
        return;
    }

    /*
     * SUPPORT BOTH:
     * 1. ServiceNow sys_id
     * 2. Interview ID such as INT007
     */

    var found = false;

    // First try as sys_id
    if (gr.get(identifier)) {
        found = true;
    }

    // If not found, try Interview ID field
    if (!found) {

        gr.initialize();

        var lookup = new GlideRecord('x_snc_campus360_mock_interview');

        lookup.addQuery('interview_id', identifier);
        lookup.setLimit(1);
        lookup.query();

        if (lookup.next()) {
            gr = lookup;
            found = true;
        }
    }

    // Record not found
    if (!found) {
        data.message = 'No Mock Interview record found for: ' + identifier;
        return;
    }

    // Display Interview ID
    data.interviewNumber = gr.getValue('interview_id');

    /*
     * Validate current QR status
     */

    var qrStatus = gr.getValue('qr_status');
    var attendanceStatus = gr.getValue('attendance_status');

    // Already marked
    if (attendanceStatus == 'Present') {

        data.success = true;
        data.message =
            'Attendance has already been marked for Interview ' +
            gr.getValue('interview_id') + '.';

        return;
    }

    // QR must be Generated
    if (qrStatus != 'Generated') {

        data.message =
            'This QR code is not valid. Current QR Status: ' +
            qrStatus;

        return;
    }

    /*
     * Mark attendance
     */

    gr.setValue('attendance_status', 'Present');
    gr.setValue('qr_status', 'Scanned');

    var updated = gr.update();

    if (updated) {

        data.success = true;

        data.message =
            'Attendance marked successfully. Interview = ' +
            gr.getValue('interview_id');

    } else {

        data.message =
            'Unable to update the Mock Interview record.';
    }

})();
